properties.query:
// rule detects brute force attacks on Forti-VPNs
// first check for any IP with more than 50 failed login events
let brute_force_ips = CommonSecurityLog
| where Message == "SSL user failed to logged in"
| summarize FailedLogins = count() by DestinationIP
| where FailedLogins > 50;
// now check for logs from that IP and show the usernames it is attempting
CommonSecurityLog
| where DestinationIP in (brute_force_ips)
| project SourceIP = DestinationIP, Username = DestinationUserName
| summarize count() by SourceIP,Username
| order by count_
